export type CrmCompaniesTableLabels = {
  caption?: string
  name?: string
  status?: string
  owner?: string
  pipeline?: string
  score?: string
  activity?: string
  selectAll?: string
  selectRow?: (company: CrmCompany) => string
  openRow?: (company: CrmCompany) => string
  empty?: string
  loading?: string
  selected?: (count: number) => string
  range?: (start: number, end: number, total: number) => string
