  sort?: CrmSort
  defaultSort?: CrmSort
  onSortChange?: (sort: CrmSort) => void
  selectedIds?: string[]
  defaultSelectedIds?: string[]
  onSelectedIdsChange?: (ids: string[]) => void
  page?: number
  defaultPage?: number
  pageSize?: number
  onPageChange?: (page: number) => void
  onRowOpen?: (company: CrmCompany) => void
  onExport?: (rows: readonly CrmCompany[]) => void
