/** Adapted from Arc UI (MIT). */

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from "react"
import { AnimatePresence, animate, motion, useInView, useMotionValue, useMotionValueEvent, useReducedMotion, useTransform, type Variants } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export interface SparklineProps {
  data: number[]
  label: string
  value?: string
  change?: string
  tone?: "accent" | "success" | "warning" | "danger"
  width?: number
  height?: number
  /** One label per point, such as a date. It replaces the change while that point is scrubbed. */
  labels?: string[]
  /** Formats a scrubbed point for the headline. Defaults to a grouped number. */
  formatValue?: (value: number, index: number) => string
  /** A quiet neutral fill under the line. */
  area?: boolean
  /** Pointer and keyboard scrubbing through the points. */
  interactive?: boolean
  className?: string
  classNames?: SparklineClassNames
}

export type SparklineClassNames = {
  root?: string
  caption?: string
  label?: string
  value?: string
  change?: string
  plot?: string
}

const toneClass = {
  accent: "text-primary",
  success: "text-[color:var(--chart-2)]",
  warning: "text-[color:var(--chart-4)]",
  danger: "text-destructive",
} as const

const rise: Variants = {
  hidden: (direction: number) => ({ opacity: 0, y: `${0.3 * direction}em`, filter: `blur(${motionPresets.blur.soft}px)` }),
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.standard, ease: [...motionPresets.ease.enter] } },
  gone: (direction: number) => ({ opacity: 0, y: `${-0.3 * direction}em`, filter: `blur(${motionPresets.blur.subtle}px)`, transition: { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } }),
}
const fade: Variants = {
  hidden: { opacity: 0, y: 0, filter: "blur(0px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
  gone: { opacity: 0, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
}
const amountIn = (text: string) => Number(text.replace(/,/g, "").replace(/−/g, "-").match(/-?\d+(?:\.\d+)?/)?.[0] ?? NaN)
const grouped = new Intl.NumberFormat("en-US")
const draw = { duration: motionPresets.duration.considered * 1.75, ease: [...motionPresets.ease.inOut] } as const
const quick = { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } as const

type Chunk = { slot: string; key: string; text: string }

function chunksOf(text: string, whole: boolean): Chunk[] {
  if (!text) return []
  if (whole) return [{ slot: "all", key: text, text }]
  if (!/\p{L}/u.test(text)) return [...text].map((char, index, all) => ({ slot: `n${all.length - index}`, key: char, text: char }))
  const words = text.split(/(?<=\s)/)
  return words.map((word, index) => ({ slot: `w${index}`, key: words.slice(0, index + 1).join(""), text: word }))
}

function Roll({ text, direction, whole = false, morph = false, className }: { text: string; direction?: number; whole?: boolean; morph?: boolean; className?: string }) {
  const reduceMotion = !!useReducedMotion()
  const sizer = useRef<HTMLSpanElement>(null)
  const width = useMotionValue<number | "auto">("auto")
  const [shown, setShown] = useState({ text, direction: 1 })
  if (shown.text !== text) setShown({ text, direction: direction ?? (amountIn(text) < amountIn(shown.text) ? -1 : 1) })
  useEffect(() => {
    const node = sizer.current
    if (!node || typeof ResizeObserver === "undefined") return
    let measured: string | null = null
    const observer = new ResizeObserver(([entry]) => {
      const next = entry.borderBoxSize?.[0]?.inlineSize ?? node.offsetWidth
      if (measured !== null && measured !== node.textContent && !reduceMotion) animate(width, next, motionPresets.spring.morph)
      else width.jump(next)
      measured = node.textContent
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [morph, reduceMotion, width])
  const numeric = !whole && !/\p{L}/u.test(text)
  const variants = reduceMotion ? fade : rise
  const anchor = numeric ? "right" : "left"
  return (
    <motion.span className={cn("relative inline-flex max-w-full overflow-x-clip align-top whitespace-pre", numeric && "justify-end", className)} style={morph ? { width } : undefined}>
      {morph ? <span ref={sizer} className="pointer-events-none absolute top-0 left-0 whitespace-pre invisible" aria-hidden="true">{text}</span> : null}
      <span className="relative inline-block whitespace-pre">
        <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
          {chunksOf(text, whole).map((chunk) => (
            <motion.span key={chunk.slot} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">
              <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
                <motion.span key={chunk.key} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">{chunk.text}</motion.span>
              </AnimatePresence>
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </motion.span>
  )
}

type Point = [number, number]
const inset = 5
const cap = 1.25
const grid = Array.from({ length: 161 }, (_, index) => index / 160)

function curveFor(data: number[]): Point[] {
  const min = Math.min(...data)
  const span = Math.max(...data) - min
  const ys = data.map((value) => (span ? (value - min) / span : 0.5))
  const last = ys.length - 1
  const step = 1 / last
  const slopes = ys.slice(1).map((y, index) => (y - ys[index]) / step)
  const tangents = ys.map((_, index) => (index === 0 || index === last ? slopes[0] : (Math.sign(slopes[index - 1]) + Math.sign(slopes[index])) * Math.min(Math.abs(slopes[index - 1]), Math.abs(slopes[index]), Math.abs(slopes[index - 1] + slopes[index]) / 4) || 0))
  if (last > 1) {
    tangents[0] = (3 * slopes[0] - tangents[1]) / 2
    tangents[last] = (3 * slopes[last - 1] - tangents[last - 1]) / 2
  }
  const samples = Math.max(1, Math.min(16, Math.round(128 / last)))
  const points: Point[] = []
  for (let index = 0; index < last; index++) {
    for (let sample = 0; sample < samples; sample++) {
      const t = sample / samples
      const t2 = t * t
      const t3 = t2 * t
      const y = (2 * t3 - 3 * t2 + 1) * ys[index] + (t3 - 2 * t2 + t) * step * tangents[index] + (3 * t2 - 2 * t3) * ys[index + 1] + (t3 - t2) * step * tangents[index + 1]
      points.push([(index + t) * step, Math.min(1, Math.max(0, y))])
    }
  }
  points.push([1, ys[last]])
  return points
}

function heightAt(shape: Point[], x: number) {
  let low = 0
  let high = shape.length - 1
  if (x <= shape[low][0]) return shape[low][1]
  if (x >= shape[high][0]) return shape[high][1]
  while (high - low > 1) {
    const middle = (low + high) >> 1
    if (shape[middle][0] < x) low = middle
    else high = middle
  }
  const [x0, y0] = shape[low]
  const [x1, y1] = shape[high]
  return x1 === x0 ? y1 : y0 + ((y1 - y0) * (x - x0)) / (x1 - x0)
}

function geometryOf(shape: Point[], w: number, h: number, at: number) {
  const toY = (y: number) => inset + (1 - y) * (h - inset * 2)
  const points = shape.map(([x, y]): Point => [x * w, toY(y)])
  const pairs = points.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`)
  const cx = at * w
  const cy = toY(heightAt(shape, at))
  return { points, line: pairs.join(" "), trail: `M${pairs.join("L")}`, fill: `M${pairs.join("L")}L${w},${h}L0,${h}Z`, dot: `${cx},${cy} ${cx},${cy}`, cx }
}

function tipAt(points: Point[], progress: number) {
  const steps = points.slice(1).map(([x, y], index) => Math.hypot(x - points[index][0], y - points[index][1]))
  let left = progress * steps.reduce((sum, step) => sum + step, 0)
  for (let index = 0; index < steps.length; index++) {
    if (left <= steps[index]) return points[index][0] + (points[index + 1][0] - points[index][0]) * (steps[index] ? left / steps[index] : 1)
    left -= steps[index]
  }
  return points[points.length - 1][0]
}

export function Sparkline({ data, label, value, change, tone = "accent", width = 160, height = 52, labels, formatValue, area = true, interactive = true, className, classNames }: SparklineProps) {
  const safeData = data.length > 1 ? data : [data[0] ?? 0, data[0] ?? 0]
  const last = safeData.length - 1
  const key = safeData.join(",")
  const target = useMemo(() => curveFor(key.split(",").map(Number)), [key])
  const description = `${label}: ${value ?? safeData[last]}. ${change ?? ""}`.trim()
  const uid = `sparkline${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const ref = useRef<HTMLElement>(null)
  const plot = useRef<HTMLDivElement>(null)
  const inView = useInView(ref, { once: true, amount: 0.5 })
  const reduceMotion = !!useReducedMotion()
  const [box, setBox] = useState({ w: width, h: height })
  const [active, setActive] = useState<number | null>(null)
  const [landed, setLanded] = useState(false)
  const index = active === null ? null : Math.min(active, last)
  const [moved, setMoved] = useState({ index, direction: 1 })
  if (moved.index !== index) setMoved({ index, direction: index === null || moved.index === null ? 1 : Math.sign(index - moved.index) || 1 })

  const [first] = useState(() => geometryOf(target, width, height, 1))
  const shape = useRef(target)
  const size = useRef(box)
  const drawn = useMotionValue(0)
  const cursor = useMotionValue(1)
  const line = useMotionValue(first.line)
  const trail = useMotionValue(first.trail)
  const fill = useMotionValue(first.fill)
  const dot = useMotionValue(first.dot)
  const cursorX = useMotionValue(first.cx)
  const lit = useMotionValue(first.cx + cap + 16)
  const dim = useMotionValue(first.cx + cap)
  const reveal = useMotionValue(0)
  const lineOpacity = useTransform(drawn, (progress) => (progress > 0.001 ? 1 : 0))
  const stroke = toneClass[tone]

  const paint = useCallback(() => {
    const { w, h } = size.current
    const progress = drawn.get()
    const next = geometryOf(shape.current, w, h, cursor.get())
    line.set(next.line)
    trail.set(next.trail)
    fill.set(next.fill)
    dot.set(next.dot)
    cursorX.set(next.cx)
    lit.set(next.cx + cap + 16)
    dim.set(next.cx + cap)
    reveal.set(progress >= 1 ? w + 32 : tipAt(next.points, progress) + 16)
  }, [cursor, cursorX, dim, dot, drawn, fill, line, lit, reveal, trail])
  useMotionValueEvent(cursor, "change", paint)
  useMotionValueEvent(drawn, "change", paint)

  useLayoutEffect(() => {
    const node = plot.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      const w = node.clientWidth
      if (w) setBox((current) => (Math.abs(current.w - w) < 0.5 ? current : { w, h: (w * height) / width }))
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [height, width])
  useLayoutEffect(() => {
    size.current = box
    paint()
  }, [box, paint])

  useEffect(() => {
    if (reduceMotion) {
      drawn.jump(1)
      const frame = requestAnimationFrame(() => setLanded(true))
      return () => cancelAnimationFrame(frame)
    }
    if (!inView) return
    const controls = animate(drawn, 1, { ...draw, onComplete: () => setLanded(true) })
    return () => controls.stop()
  }, [drawn, inView, reduceMotion])

  useEffect(() => {
    const from = shape.current
    if (from === target) return
    if (reduceMotion) {
      shape.current = target
      paint()
      return
    }
    const xs = [...new Set([...grid, ...target.map(([x]) => x)])].sort((a, b) => a - b)
    const start = xs.map((x) => heightAt(from, x))
    const goal = xs.map((x) => heightAt(target, x))
    const controls = animate(0, 1, {
      ...motionPresets.spring.smooth,
      onUpdate: (progress) => {
        shape.current = xs.map((x, at): Point => [x, start[at] + (goal[at] - start[at]) * progress])
        paint()
      },
      onComplete: () => {
        shape.current = target
        paint()
      },
    })
    return () => controls.stop()
  }, [paint, reduceMotion, target])

  useEffect(() => {
    const to = index === null ? 1 : index / last
    if (reduceMotion) {
      cursor.jump(to)
      return
    }
    const controls = animate(cursor, to, motionPresets.spring.snappy)
    return () => controls.stop()
  }, [cursor, index, last, reduceMotion])

  const scrubbing = index !== null
  const format = (at: number) => (formatValue ? formatValue(safeData[at], at) : grouped.format(safeData[at]))
  const point = format(index ?? last)
  const when = labels?.[index ?? last]
  const headline = value === undefined ? undefined : scrubbing ? point : value
  const aside = index === null ? change ?? "" : value === undefined ? [point, when].filter(Boolean).join(" · ") : when ?? `${index + 1} of ${last + 1}`
  const pointAt = (clientX: number) => {
    const rect = plot.current?.getBoundingClientRect()
    return rect?.width ? Math.max(0, Math.min(last, Math.round(((clientX - rect.left) / rect.width) * last))) : last
  }
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape" && scrubbing) {
      event.preventDefault()
      setActive(null)
      return
    }
    const from = index ?? last
    const page = Math.max(1, Math.round((last + 1) / 6))
    const next = ({ ArrowLeft: from - 1, ArrowDown: from - 1, ArrowRight: from + 1, ArrowUp: from + 1, PageDown: from - page, PageUp: from + page, Home: 0, End: last } as Record<string, number>)[event.key]
    if (next === undefined) return
    event.preventDefault()
    setActive(Math.max(0, Math.min(last, next)))
  }
  const scrub = interactive
    ? {
        role: "slider" as const,
        tabIndex: 0,
        "aria-label": `${label}, explore values`,
        "aria-valuemin": 1,
        "aria-valuemax": last + 1,
        "aria-valuenow": (index ?? last) + 1,
        "aria-valuetext": `${when ?? (index === null ? "Latest" : `Point ${index + 1} of ${last + 1}`)}: ${point}`,
        onPointerDown: (event: PointerEvent<HTMLDivElement>) => setActive(pointAt(event.clientX)),
        onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType === "mouse" || event.buttons) setActive(pointAt(event.clientX))
        },
        onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType !== "mouse") setActive(null)
        },
        onPointerLeave: () => setActive(null),
        onPointerCancel: () => setActive(null),
        onBlur: () => setActive(null),
        onKeyDown,
      }
    : {}

  return (
    <figure ref={ref} data-slot="sparkline" aria-label={description} className={cn("grid min-w-0 gap-3 text-foreground", className, classNames?.root)}>
      <figcaption data-slot="sparkline-caption" className={cn("flex min-w-0 items-baseline gap-2 text-sm text-muted-foreground", classNames?.caption)}>
        <span data-slot="sparkline-label" className={cn("min-w-0 overflow-hidden whitespace-nowrap", classNames?.label)}>
          <Roll text={label} whole />
        </span>
        {headline !== undefined ? (
          <strong data-slot="sparkline-value" className={cn("ml-auto text-lg font-medium text-foreground tabular-nums", classNames?.value)}>
            <Roll text={headline} morph />
          </strong>
        ) : null}
        <small data-slot="sparkline-change" className={cn("shrink-0 text-xs font-medium tabular-nums transition-colors", stroke, scrubbing && "text-muted-foreground", classNames?.change)}>
          <Roll text={aside} direction={scrubbing ? moved.direction : undefined} morph />
        </small>
      </figcaption>
      <div
        ref={plot}
        data-slot="sparkline-plot"
        data-interactive={interactive || undefined}
        className={cn("relative min-w-0 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-offset-8", interactive && "cursor-default touch-pan-y select-none", classNames?.plot)}
        {...scrub}
      >
        <svg data-slot="sparkline-chart" className="block h-auto w-full overflow-visible" viewBox={`0 0 ${box.w} ${box.h}`} aria-hidden="true" focusable="false">
          <defs>
            <clipPath id={`${uid}-lit`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={lit} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-dim`} clipPathUnits="userSpaceOnUse"><motion.rect x={dim} y={-16} width={box.w + 32} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-fill`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={reveal} height={box.h + 32} /></clipPath>
          </defs>
          {area ? <motion.path className={cn("fill-current stroke-none opacity-10", stroke)} d={fill} clipPath={`url(#${uid}-fill)`} /> : null}
          <line className="stroke-border" strokeWidth={1} x1="0" y1={box.h - 0.5} x2={box.w} y2={box.h - 0.5} />
          <motion.path className="fill-none stroke-border stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]" d={trail} clipPath={`url(#${uid}-dim)`} initial={false} animate={{ opacity: scrubbing && landed ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]", stroke)} points={line} clipPath={`url(#${uid}-lit)`} style={{ pathLength: drawn, opacity: lineOpacity }} />
          <motion.line className="stroke-border" strokeWidth={1} x1={cursorX} x2={cursorX} y1={0} y2={box.h} initial={false} animate={{ opacity: scrubbing ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current", stroke)} points={dot} initial={false} animate={{ opacity: landed ? 1 : 0, strokeWidth: landed ? (scrubbing ? 10 : 7) : 0 }} transition={reduceMotion ? { duration: 0 } : { opacity: quick, strokeWidth: motionPresets.spring.snappy }} strokeLinecap="round" />
        </svg>
      </div>
    </figure>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Search, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type SearchFieldClassNames = {
  root?: string
  label?: string
  shell?: string
  input?: string
  clear?: string
}

export type SearchFieldProps = Omit<React.ComponentProps<"input">, "type" | "value" | "onChange"> & {
  label: string
  value: string
  onValueChange: (value: string) => void
  classNames?: SearchFieldClassNames
}

export const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(function SearchField(
  { label, value, onValueChange, id, className, classNames, ...props },
  ref,
) {
  const generated = React.useId()
  const controlId = id ?? generated
  const reduced = useReducedMotion()
  const inputRef = React.useRef<HTMLInputElement | null>(null)

  const setRefs = (node: HTMLInputElement | null) => {
    inputRef.current = node
    if (typeof ref === "function") ref(node)
    else if (ref) ref.current = node
  }

  function clear() {
    onValueChange("")
    inputRef.current?.focus()
  }

  return (
    <div data-slot="search-field" className={cn("grid min-w-0 gap-2", className, classNames?.root)}>
      <label htmlFor={controlId} data-slot="search-field-label" className={cn("text-sm font-medium", classNames?.label)}>
        {label}
      </label>
      <div
        data-slot="search-field-shell"
        data-filled={value ? "true" : undefined}
        className={cn(
          "flex h-9 min-w-0 items-center gap-1 rounded-lg border border-input bg-transparent pr-1 pl-2.5 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
          classNames?.shell,
        )}
      >
        <Search className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
        <Input
          {...props}
          ref={setRefs}
          id={controlId}
          type="search"
          value={value}
          onChange={(event) => onValueChange(event.target.value)}
          className={cn(
            "h-8 border-0 bg-transparent px-1 shadow-none focus-visible:ring-0 dark:bg-transparent [&::-webkit-search-cancel-button]:appearance-none",
            classNames?.input,
          )}
        />
        <span className="grid size-6 shrink-0 place-items-center">
          <AnimatePresence initial={false}>
            {value ? (
              <motion.span
                key="clear"
                initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: 0.8 }}
                transition={reduced ? { duration: motionPresets.duration.instant } : motionPresets.spring.snappy}
              >
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  data-slot="search-field-clear"
                  className={classNames?.clear}
                  aria-label="Clear search"
                  onClick={clear}
                >
                  <X aria-hidden="true" />
                </Button>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </span>
      </div>
    </div>
  )
})

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

"use client"

import * as React from "react"
import { Dialog } from "radix-ui"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"

/**
 * Progressive disclosure surface.
 *
 * Opens as a right-hand peek panel and can expand left into a two-column
 * view without changing route. Built on Radix Dialog (focus trap, scroll
 * lock, Esc / click-outside). Does not import Next.js — pair with
 * `useLayeredPanelUrlState` when you want shareable URLs.
 *
 * `Header` and `ExpandToggle` sit at the top of the primary column and move
 * into the left column when the panel expands. Render them from a child
 * component that returns a fragment, or give a wrapping element `className="contents"`.
 */

export type LayeredPanelMode = "peek" | "full"

const CSS_LENGTH = /^(?:\d*\.?\d+)(?:px|rem|em|vw|vh|%)$/

type LayeredPanelContextValue = {
  open: boolean
  mode: LayeredPanelMode
  setOpen: (open: boolean) => void
  setMode: (mode: LayeredPanelMode) => void
  registerFull: (present: boolean) => void
}

const LayeredPanelContext =
  React.createContext<LayeredPanelContextValue | null>(null)

function useLayeredPanel() {
  const context = React.useContext(LayeredPanelContext)
  if (!context) {
    throw new Error("useLayeredPanel must be used within LayeredPanel.")
  }
  return context
}

function useControllable<T>({
  value,
  defaultValue,
  onChange,
}: {
  value: T | undefined
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const controlled = value !== undefined
  const current = controlled ? value : uncontrolled

  const setValue = React.useCallback(
    (next: T) => {
      if (!controlled) setUncontrolled(next)
      onChange?.(next)
    },
    [controlled, onChange],
  )

  return [current, setValue] as const
}

function cssLength(value: string | undefined, fallback: string) {
  if (!value) return fallback
  const trimmed = value.trim()
  return CSS_LENGTH.test(trimmed) ? trimmed : fallback
}

type LayeredPanelProps = {
  children?: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  mode?: LayeredPanelMode
  defaultMode?: LayeredPanelMode
  onModeChange?: (mode: LayeredPanelMode) => void
  /** Accessible name announced for the dialog. */
  title?: string
  /** Accessible description. Kept visually hidden. */
  description?: string
  /** Close button label. Default: "Close". */
  closeLabel?: string
  /** Mobile tab for the peek column. Default: "Overview". */
  mobilePeekLabel?: string
  /** Mobile tab for the full column. Default: "Profile". */
  mobileFullLabel?: string
  /** Peek width on desktop. Any single CSS length. Default: 26.25rem (420px). */
  peekWidth?: string
  /** Expanded width on desktop. Any single CSS length. Default: 70vw. */
  fullWidth?: string
  /** Hide the built-in close button when you render your own. */
  showClose?: boolean
  /** Panel surface. Merged onto the dialog content. */
  className?: string
  /** Backdrop. Default uses `bg-foreground` / `bg-background`, not a custom color. */
  overlayClassName?: string
  /** Built-in close button. */
  closeClassName?: string
  /** Mobile tab track, below 1024px. */
  tabsClassName?: string
  /** Each mobile tab button. */
  tabClassName?: string
  /** Grid that holds Header, ExpandToggle, Peek, and Full. */
  gridClassName?: string
}

function LayeredPanelRoot({
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  mode: modeProp,
  defaultMode = "peek",
  onModeChange,
  title = "Details",
  description = "Detail panel",
  closeLabel = "Close",
  mobilePeekLabel = "Overview",
  mobileFullLabel = "Profile",
  peekWidth,
  fullWidth,
  showClose = true,
  className,
  overlayClassName,
  closeClassName,
  tabsClassName,
  tabClassName,
  gridClassName,
}: LayeredPanelProps) {
  const [open, setOpenState] = useControllable({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [mode, setModeState] = useControllable({
    value: modeProp,
    defaultValue: defaultMode,
    onChange: onModeChange,
  })

  const setOpen = React.useCallback(
    (next: boolean) => {
      setOpenState(next)
      if (!next && modeProp === undefined) setModeState(defaultMode)
    },
    [defaultMode, modeProp, setModeState, setOpenState],
  )

  const setMode = React.useCallback(
    (next: LayeredPanelMode) => {
      setModeState(next)
    },
    [setModeState],
  )
  const [hasFull, setHasFull] = React.useState(false)
  const registerFull = React.useCallback((present: boolean) => {
    setHasFull(present)
  }, [])

  const panelId = React.useId().replace(/:/g, "")
  const peek = cssLength(peekWidth, "26.25rem")
  const full = cssLength(fullWidth, "70vw")
  const contentRef = React.useRef<HTMLDivElement>(null)
  const previousMode = React.useRef(mode)

  React.useEffect(() => {
    if (
      previousMode.current === "full" &&
      mode === "peek" &&
      contentRef.current
    ) {
      const active = document.activeElement
      if (!active || !contentRef.current.contains(active)) {
        contentRef.current.focus()
      }
    }
    previousMode.current = mode
  }, [mode])

  const context = React.useMemo<LayeredPanelContextValue>(
    () => ({ open, mode, setOpen, setMode, registerFull }),
    [mode, open, registerFull, setMode, setOpen],
  )

  return (
    <LayeredPanelContext.Provider value={context}>
      <Dialog.Root open={open} onOpenChange={setOpen} modal>
        <Dialog.Portal>
          <Dialog.Overlay
            data-slot="layered-panel-overlay"
            className={cn(
              "fixed inset-0 z-50 bg-foreground/40 dark:bg-background/80 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0 motion-reduce:animate-none",
              overlayClassName,
            )}
          />
          <Dialog.Content
            ref={contentRef}
            data-slot="layered-panel"
            data-panel-id={panelId}
            data-mode={mode}
            tabIndex={-1}
            onEscapeKeyDown={(event) => {
              if (mode === "full") {
                event.preventDefault()
                setMode("peek")
              }
            }}
            className={cn(
              "fixed inset-y-0 right-0 z-50 flex h-dvh max-h-dvh max-w-full flex-col overflow-hidden border-l border-border bg-background text-foreground shadow-lg outline-none lg:rounded-l-xl",
              "pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]",
              "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:slide-out-to-right data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:slide-in-from-right data-[state=open]:duration-300 data-[state=closed]:duration-300 motion-reduce:animate-none",
              className,
            )}
          >
            <style>{`
              [data-panel-id="${panelId}"] { width: min(100%, ${peek}); transition: width 280ms cubic-bezier(0.32, 0.72, 0, 1); }
              [data-panel-id="${panelId}"][data-mode="full"] { width: min(100%, ${full}); }
              [data-panel-id="${panelId}"] .lp-grid { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); }
              @media (min-width: 1024px) {
                [data-panel-id="${panelId}"][data-mode="full"] .lp-grid { grid-template-columns: minmax(0, 1fr) min(100%, ${peek}); }
              }
              @media (max-width: 1023px) {
                [data-panel-id="${panelId}"],
                [data-panel-id="${panelId}"][data-mode="full"] { width: 100%; transition: none; }
              }
              @media (prefers-reduced-motion: reduce) {
                [data-panel-id="${panelId}"] { transition: none; }
              }
            `}</style>
            <Dialog.Title className="sr-only">{title}</Dialog.Title>
            <Dialog.Description className="sr-only">
              {description}
            </Dialog.Description>
            {showClose ? (
              <Dialog.Close asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  aria-label={closeLabel}
                  className={cn(
                    "absolute top-[max(0.75rem,env(safe-area-inset-top))] right-3 z-10 active:scale-[0.96] motion-reduce:active:scale-100",
                    closeClassName,
                  )}
                >
                  <X />
                </Button>
              </Dialog.Close>
            ) : null}
            {hasFull ? (
              <div className={cn("shrink-0 px-3 pt-3 pr-14 lg:hidden", tabsClassName)}>
                <div
                  className="flex rounded-lg bg-muted p-0.5"
                  role="group"
                  aria-label="Panel sections"
                >
                  <ModeButton
                    pressed={mode === "peek"}
                    onClick={() => setMode("peek")}
                    className={tabClassName}
                  >
                    {mobilePeekLabel}
                  </ModeButton>
                  <ModeButton
                    pressed={mode === "full"}
                    onClick={() => setMode("full")}
                    className={tabClassName}
                  >
                    {mobileFullLabel}
                  </ModeButton>
                </div>
              </div>
            ) : null}
            <div className={cn("lp-grid grid min-h-0 flex-1", gridClassName)}>
              {children}
            </div>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    </LayeredPanelContext.Provider>
  )
}

function ModeButton({
  pressed,
  onClick,
  className,
  children,
}: {
  pressed: boolean
  onClick: () => void
  className?: string
  children: React.ReactNode
}) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={onClick}
      className={cn(
        "h-8 flex-1 rounded-lg text-sm font-medium transition-transform active:scale-[0.96] motion-reduce:active:scale-100",
        pressed
          ? "bg-background text-foreground shadow-sm"
          : "text-muted-foreground",
        className,
      )}
    >
      {children}
    </button>
  )
}

type ColumnProps = {
  children?: React.ReactNode
  className?: string
  contentClassName?: string
}

function Peek({ children, className, contentClassName }: ColumnProps) {
  const { mode } = useLayeredPanel()
  return (
    <div
      data-slot="layered-panel-peek"
      className={cn(
        "col-start-1 row-start-3 min-h-0",
        mode === "full" &&
          "max-lg:hidden lg:col-start-2 lg:row-span-3 lg:row-start-1 lg:border-l lg:border-border",
        className,
      )}
    >
      <ScrollArea className="h-full">
        <div
          className={cn(
            "flex min-h-full flex-col",
            mode === "full" && "lg:pt-12",
            contentClassName,
          )}
        >
          {children}
        </div>
      </ScrollArea>
    </div>
  )
}
Peek.displayName = "LayeredPanel.Peek"
;(Peek as typeof Peek & { slot: string }).slot = "peek"

function Full({ children, className, contentClassName }: ColumnProps) {
  const { mode, registerFull } = useLayeredPanel()
  React.useLayoutEffect(() => {
    registerFull(true)
    return () => registerFull(false)
  }, [registerFull])

  return (
    <div
      data-slot="layered-panel-full"
      inert={mode === "full" ? undefined : true}
      className={cn(
        "col-start-1 row-start-3 min-h-0",
        mode === "full" ? "block" : "hidden",
        className,
      )}
    >
      <ScrollArea className="h-full">
        <div className={cn("flex min-h-full flex-col", contentClassName)}>
          {children}
        </div>
      </ScrollArea>
    </div>
  )
}
Full.displayName = "LayeredPanel.Full"
;(Full as typeof Full & { slot: string }).slot = "full"

function Header({
  children,
  className,
}: {
  children?: React.ReactNode
  className?: string
}) {
  return (
    <div
      data-slot="layered-panel-header"
      className={cn(
        "col-start-1 row-start-1 flex flex-col gap-3 px-5 pt-5 pr-14 pb-1",
        className,
      )}
    >
      {children}
    </div>
  )
}
Header.displayName = "LayeredPanel.Header"
;(Header as typeof Header & { slot: string }).slot = "header"

type ExpandToggleProps = {
  /** Label while the panel is peeked. Default: "View full profile". */
  expandLabel?: string
  /** Label while the panel is expanded. Default: "Close profile". */
  collapseLabel?: string
  /** Wrapper that places the control on the grid. */
  className?: string
  /** Passed to the host `Button`. Does not replace its variant. */
  buttonClassName?: string
}

function ExpandToggle({
  expandLabel = "View full profile",
  collapseLabel = "Close profile",
  className,
  buttonClassName,
}: ExpandToggleProps) {
  const { mode, setMode } = useLayeredPanel()
  const expanded = mode === "full"

  return (
    <div className={cn("col-start-1 row-start-2 px-5 py-3", className)}>
      <Button
        type="button"
        variant="secondary"
        aria-expanded={expanded}
        onClick={() => setMode(expanded ? "peek" : "full")}
        className={cn(
          "w-full active:scale-[0.96] motion-reduce:active:scale-100",
          buttonClassName,
        )}
      >
        {expanded ? collapseLabel : expandLabel}
      </Button>
    </div>
  )
}
ExpandToggle.displayName = "LayeredPanel.ExpandToggle"
;(ExpandToggle as typeof ExpandToggle & { slot: string }).slot = "toggle"

type DetailSectionProps = {
  title: string
